#include<iostream>#include<vector>using namespace std; int main() {    string s;    cin >> s;        int n = s.length();     int lowerCase = 0 , upperCase = 0;    for(int i=0; i<n; i++){        if(s[i] >= 'a' && s[i] <= 'z'){            lowerCase++;        }        else{            upperCase++;        }    }     if(lowerCase >= upperCase){        for(int i=0; i<n; i++){            if(s[i] >= 'A' && s[i] <= 'Z'){                s[i] = s[i] + 32;            }        }    }    else{        for(int i=0; i<n; i++){            if(s[i] >= 'a' && s[i] <= 'z'){                s[i] = s[i] - 32;            }        }    }    cout << s;     return 0;}